    private function __construct()
    {
    }

    public static function exists(string $code): bool
    {
        return isset(self::NAMES[$code]);
    }

    public static function nameOf(string $code): string
    {
        return self::NAMES[$code];
    }

    public static function categoryOf(string $code): SubdivisionCategory
    {
        return SubdivisionCategory::from(self::CATEGORIES[$code]);
    }

    public static function forCountry(Alpha2Code $alpha2): Subdivisions
    {
        $template = '%s-';
        $prefix = sprintf($template, $alpha2->value);

        $codes = array_filter(
            array_keys(self::NAMES),
            static fn(string $code): bool => str_starts_with($code, $prefix)
        );

        $subdivisions = array_map(
            static fn(string $code): Subdivision => Subdivision::fromString(code: $code),
            $codes
        );

        return Subdivisions::createFrom(elements: $subdivisions);
    }
}
